import json
from pathlib import Path
p=Path(__file__).parent;r=json.loads((p/'reviews.json').read_text())
def add(slug,country,comp,year,section,n,v,topic,tags,why,statement,src,page,solution=None,notes=''):
 (p/(slug+'.json')).write_text(json.dumps({'country':country,'competition':comp,'year':year,'section':section,'problem_number':str(n),'problem_markdown':statement or 'See the official paper for the full statement.','solutions_markdown':[],'booklet_title':comp+' official solutions'},ensure_ascii=False,indent=2))
 su=src+f'#page={page}';r[slug]={'difficulty':v,'topic':topic,'tags':tags,'reason':why,'sourceUrl':src,'solutionUrl':su,'solutionKind':'original-exposition' if solution else 'source-link','solution':solution or '[Official worked solution]('+su+').','sourceName':('Albanian Mathematical Association / QSHA' if country=='Albania' else 'Ispitni centar Crne Gore')+' — official paper and solutions','license':'Original competition rights retained; concise English mathematical paraphrase.','notes':notes}
 if v is None:r[slug]['quarantine']=True
alburls={(2025,'upper'):'https://www.ama.org.al/asset/882c8450-a497-4232-98c7-438141e71345/',(2025,'lower'):'https://www.ama.org.al/asset/58428ba7-2a27-46cc-95f8-eaa546d0a6a0/',(2026,'upper'):'https://www.ama.org.al/asset/02f09384-a96b-4c91-9974-dab5de844732/',(2026,'lower'):'https://www.ama.org.al/asset/22e384ba-6e16-403f-9928-84c580c53faf/'}
alb={
(2025,'upper'):[(3.5,'Geometry','Use midpoint and diameter geometry to obtain an altitude, then compute it by area and a median length.',None),(5.5,'Algebra','Homogenize and connect the elementary symmetric sums through a sixth-degree factorization; two inequalities must be combined in the correct direction.',r'For positive $x,y,z$ with $xyz=1$, prove $$\sqrt[5]{\frac{x^2+y^2+z^2}{3}}\le\frac{x+y+z}{3}.$$'),(2.5,'Number theory','The geometric sum is congruent to b modulo a-1, so the two greatest common divisors coincide.',None),(4,'Combinatorics','Count the four possible positions of the digit block with divisibility conditions, then remove all double counts.',r'How many five-digit positive integers are multiples of 15 and contain two consecutive digits equal to 15?'),(3,'Algebra','Swap x and its reciprocal to solve for f; AM-GM and x+1/x>=2 prove the minimum without the source’s calculus.',None)],
(2025,'lower'):[(1.5,'Algebra','Factor the first quadratic as (x-2y)(x-3y); the second equation restricts the integral solutions.',None),(1.5,'Algebra','Translate the saved journey time into one quadratic equation.',None),(2.5,'Algebra','Use the lower rational bounds 2,5/3,4/3 for the three roots.',None),(None,'Geometry','Quarantined: the statement says only a 1:2 ratio but the solution assumes angle BAM is the smaller one; the reversed assignment need not yield the claimed conclusion.',None),(3,'Number theory','Set c=2b; divisibility of ac and a squared plus c squared by a+c makes the squared-factor assertion immediate.',None)],
(2026,'upper'):[(3.5,'Geometry','The metric data force an isosceles triangle; midpoint and cyclic-angle relations reduce the target to similar triangles.',None),(3,'Algebra','Adjacent products form an arithmetic sequence, giving an alternating double-factorial product.',None),(5,'Number theory','Factor y squared minus one; the full power of two lies in one of the two adjacent even factors, leaving only two bounded odd multipliers.',r'Find all integer pairs $(x,y)$ satisfying $$y^2=1+2^{2x+1}+2^x.$$'),(4,'Algebra','Factor each radicand using the constraint, then AM-GM converts the sum into three complementary fraction pairs.',r'If $x,y,z>0$ and $xy+yz+zx=3$, prove $$\frac{x}{\sqrt{x^2+3}}+\frac{y}{\sqrt{y^2+3}}+\frac{z}{\sqrt{z^2+3}}\le\frac32.$$'),(None,'Algebra','Quarantined: the published answer f(x)=x omits f(x)=-x and arbitrary additive involutions. The intended elementary classification is not valid over all real functions.',None)],
(2026,'lower'):[(3,'Geometry','An auxiliary midpoint gives an isosceles triangle and the doubled angle.',None),(3,'Number theory','Factor into two prime sums; parity forces the prime 2, and the small divisor list completes the classification.',None),(3,'Algebra','Complement the variables so their sum is one, then multiply three elementary AM-GM inequalities.',None),(2.5,'Algebra','Monotonicity forces the substituted variables equal; one squaring gives the unique solution.',None),(1,'Algebra','The two work-rate equations give eight and twenty-four days.',None)]}
for (year,lev),rows in alb.items():
 for n,(v,t,why,st) in enumerate(rows,1):
  page=({1:1,2:3,3:4,4:5,5:7}[n] if year==2025 and lev=='upper' else n if year==2025 else n+1)
  sol=None;note=''
  if (year,lev,n)==(2025,'upper',2):
   sol=r'Write $p=x+y+z$, $q=xy+yz+zx$, and $r=xyz$. We have $q^2\ge3pr$ and $$p^6-27q^2(p^2-2q)=(p^2-3q)^2(p^2+6q)\ge0.$$ Therefore $p^6\ge81pr(p^2-2q)$, so $p^5\ge81r(x^2+y^2+z^2)$. With $r=1$, this is the required fifth-power inequality. Equality holds at $x=y=z=1$.';note='Original exposition corrects an extraneous factor in the published intermediate algebra.'
  if (year,lev,n)==(2026,'upper',3):
   sol=r'Negative $x$ give a value strictly between 1 and 2, or the value 2, so are impossible. The cases $x=0,1,2$ leave only $y=\pm2$ at $x=0$. For $x\ge3$, replace $y$ by $|y|$. Since $(y-1)(y+1)=2^x(2^{x+1}+1)$ and the two factors have gcd 2, $y=2^{x-1}a+\varepsilon$ for an odd positive integer $a$ and $\varepsilon\in\{-1,1\}$. Also $y<3\cdot2^{x-1}$, so $a<4$, hence $a=1$ or $3$. Substitution yields $$2^{x-2}(a^2-8)=1-\varepsilon a.$$ The value $a=1$ is impossible. For $a=3$ only $\varepsilon=-1$ works, giving $x=4,y=23$. Thus the pairs are $(0,\pm2)$ and $(4,\pm23)$.'
  add(f'alb_{year}_{lev}_{n}','Albania','Albanian National Mathematical Olympiad',year,'Final Round — '+('Upper Secondary (AML)' if lev=='upper' else 'Lower Secondary (AMU)'),n,v,t,[],why,st,alburls[year,lev],page,sol,note)
