mne={
(2025,'lower'):[(2.5,'Number theory','The remainder bounds restrict the square divisor to three possibilities, checked in the division identity.',None),(3,'Algebra','Floor bounds and reciprocal AM-GM give an integer greater than 3; a small explicit triple attains 4.',None),(3.5,'Geometry','Identify the circumcentre of BCI as the arc midpoint on AI; reflection in AI proves the equal angles.',None),(4.5,'Combinatorics','Pad with leading zeros and subtract the zero-nine and one-nine cases; a final digit is uniquely determined modulo nine.',r'For a positive integer $n$, count the positive integers having at most $n$ decimal digits, divisible by 9, and containing at least two digits equal to 9.')],
(2025,'upper'):[(5,'Number theory','Integer-polynomial divisibility determines the two input values, then successive factor-theorem steps parametrize every polynomial.',r'Let $P\in\mathbb Z[x]$, $P(0)=0$, and suppose positive integers $a>b$ satisfy $P(a)=2025$ and $P(b)=2027$. Determine $P(1)$ and all possible polynomials $P$. You may use that 2027 is prime.'),(4.5,'Number theory','Use the smallest prime divisor and its coprimality with n to force the multiplicative order to one.',r'Find all positive integers $n$ such that $n\mid5^n-4^n$.'),(4,'Combinatorics','Pair complementary digit strings, count multisets, and correct for constant strings counted twice.',r'A four-digit number with no zero digit is monotone if its digits are weakly increasing or weakly decreasing. Find the sum of all such numbers.'),(5.5,'Geometry','Convert the product into power of a point, minimize distance on an auxiliary semicircle, and connect the equality case to cyclicity.',r'On a circle with centre $O$ and diameter $AB$, fix $C\ne A,B$. Let $D$ vary on the open arc $AB$ opposite $C$, and let $E$ be the foot from $B$ to $CD$. Prove that $CE\cdot ED$ is greatest precisely when $B,O,E,D$ are concyclic.')],
(2026,'lower'):[(3,'Number theory','A hypothetical integer between the two expressions forces n=k(k-1), contradicting oddness.',None),(2,'Geometry','Internal and external angle-bisector ratios, together with the midpoint, give the ratio three directly.',None),(3,'Combinatorics','There are six valid first digits and exactly seven extensions of either nonzero residue class.',None),(4.5,'Number theory','Coprimality extracts a common square-free factor dividing eight; parity and a modulo-three obstruction force it to one.',r'Pairwise coprime positive integers $a,b,c,d$ satisfy $$c^2(a^2+d^2)=b^2(9a^2+d^2).$$ Prove that both $a^2+d^2$ and $9a^2+d^2$ are perfect squares.')],
(2026,'upper'):[(5,'Algebra','After proving evenness and the scaling at two, a strong induction handles odd multiples and then extends to every rational.',r'Find all $f:\mathbb Q\to\mathbb Q$ such that $$f(x+2y)+f(2x-y)=5f(x)+5f(y)\quad(x,y\in\mathbb Q).$$'),(5,'Number theory','Separate palindromes; congruences modulo ten, five, and nine leave a short list of nonpalindromic digit patterns.',r'Find all four-digit integers $\overline{abcd}$ satisfying $d\,\overline{abcd}=a\,\overline{dcba}$.'),(5,'Combinatorics','A complement double count supplies a six-element hitting set; two disjoint five-element blocks show sharpness.',r'For any twenty distinct three-element subsets of $\{1,\ldots,10\}$, find the least guaranteed size of a set meeting all twenty.'),(6,'Geometry','Parallelograms and equal powers give three perpendicular bisectors; reflecting the orthocentre in the circumcentre identifies the concurrency point.',r'In acute $ABC$ with orthocentre $H$, draw through $H$ the parallels to $BC,CA,AB$, meeting $(AB,AC),(BC,BA),(CA,CB)$ respectively at $(D,E),(P,Q),(X,Y)$. Prove that the perpendiculars from $A,B,C$ to $QX,DY,EP$, respectively, are concurrent.')]
}
for (year,lev),rows in mne.items():
 for n,(v,t,why,st) in enumerate(rows,1):
  page=({1:4,2:4,3:5,4:6}[n] if year==2025 and lev=='upper' else 4 if year==2025 else {1:3,2:4,3:5,4:6}[n] if lev=='upper' else 4 if n>=3 else 3)
  sol=None;note=''
  if (year,lev,n)==(2025,'lower',4):
   sol=r'The answer is zero for $n=1$. For $n\ge2$, pad all numbers to length $n$ with leading zeros. There are $(10^n-1)/9$ positive multiples of nine. Of these, $9^{n-1}-1$ contain no nine: choose the first $n-1$ digits from 0 through 8, choose the last uniquely modulo nine, and remove the all-zero string. Exactly $n9^{n-2}$ contain one nine: choose its position and choose the other digits, whose sum must be zero modulo nine. Subtracting gives $$\frac{10^n-1}{9}-9^{n-1}+1-n9^{n-2}.$$';note='The n=1 case is stated separately, avoiding the negative-exponent edge case in the source formula.'
  add(f'mne_{year}_{lev}_{n}','Montenegro','Montenegro National Mathematics Competition',year,'National Round — Secondary Years '+('III–IV' if lev=='upper' else 'I–II'),n,v,t,[],why,st,mneurls[year,lev],page,sol,note)
